import math

def min_eating_speed(piles, h):
    lo, hi = 1, max(piles)

    def hours_needed(k):
        return sum(math.ceil(pile / k) for pile in piles)

    while lo < hi:
        mid = (lo + hi) // 2
        if hours_needed(mid) <= h:
            hi = mid
        else:
            lo = mid + 1

    return lo

